Here is a simple example of a red heart fractal in p5.js and WebGL. The fractal is created using the Sierpinski triangle algorithm.

```javascript
let angle = 0;
let heart;

function setup() {
  createCanvas(600, 600, WEBGL);
  heart = new Heart();
}

function draw() {
  background(0);
  rotateX(radians(angle));
  rotateY(radians(angle));
  heart.display();
  angle += 0.5;
}

class Heart {
  constructor() {
    this.w = 100;
    this.h = 150;
  }

  display() {
    push();
    translate(0, 0, -200);
    noFill();
    stroke(255, 0, 0);
    strokeWeight(2);
    beginShape();
    this.triangle(-this.w/2, -this.h/2, this.w/2, -this.h/2, 0, this.h/2);
    this.sierpinski(-this.w/2, -this.h/2, this.w/2, -this.h/2);
    endShape(CLOSE);
    pop();
  }

  sierpinski(x1, y1, x2, y2) {
    let midX = (x1 + x2) / 2;
    let midY = (y1 + y2) / 2;

    if (abs(midX) < this.w/2 && abs(midY) < this.h/2) {
      this.triangle(midX, midY, midX - this.w/4, midY + this.h/4, midX + this.w/4, midY + this.h/4);
      this.sierpinski(midX - this.w/4, midY + this.h/4, midX, midY, midX + this.w/4, midY + this.h/4);
    }
  }

  triangle(x1, y1, x2, y2, x3, y3) {
    vertex(x1, y1);
    vertex(x2, y2);
    vertex(x3, y3);
  }
}
```

This code creates a heart shape and then recursively calls the `sierpinski` function to create the fractal pattern. The `sierpinski` function calls itself until the points become too small to be visible.

You can adjust the variables in the `Heart` class (such as `w` and `h`) to change the size and shape of the heart. You can also adjust the parameters in the `sierpinski` function to change the complexity of the fractal pattern.

Please note that WebGL can be quite demanding, especially when dealing with complex fractals.

