      <path d="M3 5L15 5M3 9L15 9M3 13L15 13" stroke="currentColor" strokeWidth="2"></path>
    </svg>
  </div>
  <ul id="predictive-search-list" class="predictive-search-list"></ul>
</div>

/* CSS */
.predictive-search-list {
  position: absolute;
  top: 100%;
  left: 0;
  width: 100%;
  padding: 10px;
  background-color: #f6f6f6;
  border: 1px solid #ccc;
  border-radius: 10px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.predictive-search-list li {
  padding: 10px;
  border-bottom: 1px solid #ccc;
}

.predictive-search-list li:last-child {
  border-bottom: none;
}

/* JavaScript */
javascript:
  const searchInput = document.getElementById('search-input');
  const predictiveSearchList = document.getElementById('predictive-search-list');

  searchInput.addEventListener('input', async () => {
    const query = searchInput.value.trim();
    if (query.length > 2) {
      const response = await fetch(`https://www.google.com/complete/search?q=${query}&hl=en`);
      const data = await response.json();
      const predictions = data[1];

      predictiveSearchList.innerHTML = '';
      predictions.forEach(prediction => {
        const listItem = document.createElement('LI');
        listItem.textContent = prediction[0];
        predictiveSearchList.appendChild(listItem);
      });
    } else {
      predictiveSearchList.innerHTML = '';
    }
  });

  searchInput.addEventListener('hover', () => {
    predictiveSearchList.classList.add('visible');
  });
  searchInput.addEventListener('mouseleave', () => {
    predictiveSearchList.classList.remove('visible');
  });
